namespace sv_23ceae0f1551407396de490069a076a1.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the currently selected warehouse
/// and notifies subscribers when it changes.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyStateChanged();
        }
    }

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public static IReadOnlyList<Warehouse> AvailableWarehouses { get; } =
    [
        new("WH-001", "Warehouse A — Main Distribution"),
        new("WH-002", "Warehouse B — East Coast"),
        new("WH-003", "Warehouse C — West Coast"),
        new("WH-004", "Warehouse D — Returns Processing"),
    ];

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();

    public void Dispose() => OnChange = null;
}

public sealed record Warehouse(string Id, string Name);

namespace sv_23ceae0f1551407396de490069a076a1.Services;

/// <summary>
/// Scoped service that simulates checking inventory levels and broadcasts
/// alert count changes to all subscribed components in the current circuit.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private CancellationTokenSource? _pollCts;
    private int _subscriberCount;

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired whenever new alert data arrives. All subscribed components
    /// receive this notification regardless of which one triggered the poll.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate latency-free DB call returning random count 0–15
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Registers a subscriber and starts polling if this is the first one.
    /// Returns an IDisposable that unsubscribes when disposed.
    /// </summary>
    public IDisposable Subscribe(Func<Task> callback, string warehouseIdAccessor)
    {
        OnAlertCountChanged += callback;
        _subscriberCount++;

        if (_subscriberCount == 1)
        {
            StartPolling(warehouseIdAccessor);
        }

        return new Subscription(this, callback);
    }

    /// <summary>
    /// Starts polling with access to the current warehouse from WarehouseStateService.
    /// Called by the dashboard component to begin the 10-second refresh cycle.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        StopPolling();
        _pollCts = new CancellationTokenSource();
        _ = PollLoopAsync(warehouseId, _pollCts.Token);
    }

    public void StopPolling()
    {
        _pollCts?.Cancel();
        _pollCts?.Dispose();
        _pollCts = null;
    }

    /// <summary>
    /// Manually triggers a refresh (used when warehouse changes while polling is active).
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        CurrentLowStockCount = await GetLowStockCountAsync(warehouseId);
        await NotifySubscribersAsync();
    }

    private async Task PollLoopAsync(string warehouseId, CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                CurrentLowStockCount = await GetLowStockCountAsync(warehouseId);
                await NotifySubscribersAsync();
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    private async Task NotifySubscribersAsync()
    {
        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    private void Unsubscribe(Func<Task> callback)
    {
        OnAlertCountChanged -= callback;
        _subscriberCount--;

        if (_subscriberCount <= 0)
        {
            _subscriberCount = 0;
            StopPolling();
        }
    }

    public void Dispose()
    {
        StopPolling();
        OnAlertCountChanged = null;
    }

    private sealed class Subscription(InventoryAlertService service, Func<Task> callback) : IDisposable
    {
        public void Dispose() => service.Unsubscribe(callback);
    }
}

