@using sv_23ceae0f1551407396de490069a076a1.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-select" class="form-label text-white mb-0 me-2">Site:</label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            style="max-width: 280px; display: inline-block;"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.CurrentWarehouseId = newId;
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@using sv_23ceae0f1551407396de490069a076a1.Services
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseStateService WarehouseState
@implements IDisposable

<span class="alert-badge position-relative">
    <span class="bi bi-exclamation-triangle-fill-nav-menu" aria-hidden="true"></span>
    @if (AlertService.CurrentLowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill ms-1">@AlertService.CurrentLowStockCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill ms-1">0</span>
    }
</span>

@code {
    private IDisposable? _subscription;

    protected override void OnInitialized()
    {
        _subscription = AlertService.Subscribe(OnAlertUpdatedAsync, WarehouseState.CurrentWarehouseId);
    }

    private async Task OnAlertUpdatedAsync()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _subscription?.Dispose();
    }
}

@page "/dashboard"
@using sv_23ceae0f1551407396de490069a076a1.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">
    Currently viewing: <strong>@WarehouseState.CurrentWarehouseName</strong>
    (<code>@WarehouseState.CurrentWarehouseId</code>)
</p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(AlertService.CurrentLowStockCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentLowStockCount > 5 ? "text-danger" : "text-success")">
                    @AlertService.CurrentLowStockCount
                </p>
                <p class="card-text text-muted">
                    Items below minimum level
                </p>
                <small class="text-muted">Auto-refreshes every 10 seconds</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Active Warehouse</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseName</p>
                <p class="card-text text-muted">
                    Change the warehouse using the dropdown in the top bar.
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-info">●</p>
                <p class="card-text text-muted">
                    Polling is active while you are on this page.
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private IDisposable? _alertSubscription;
    private CancellationTokenSource? _pollCts;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;

        // Subscribe to alert notifications so this component re-renders on new data
        _alertSubscription = AlertService.Subscribe(OnAlertUpdatedAsync, WarehouseState.CurrentWarehouseId);

        // Start the polling loop for the current warehouse
        StartPolling();
    }

    private void StartPolling()
    {
        _pollCts?.Cancel();
        _pollCts?.Dispose();
        _pollCts = new CancellationTokenSource();
        _ = PollAsync(_pollCts.Token);
    }

    private async Task PollAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    private void OnWarehouseChanged()
    {
        // Restart polling with the new warehouse
        StartPolling();
        InvokeAsync(StateHasChanged);
    }

    private async Task OnAlertUpdatedAsync()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _pollCts?.Cancel();
        _pollCts?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
        _alertSubscription?.Dispose();
    }
}

